import os, glob, re

def load_grids():
    """Load all demo pairs and test input from current conversation."""
    d = os.path.normpath(os.environ.get('RLM_SESSION_DIR', ''))
    if not d:
        return {}

    # Find the jsonl file for this session
    session_name = os.path.basename(d)
    jsonl_path = os.path.join(os.path.dirname(d), '..', 'sessions', session_name + '.jsonl')

    if not os.path.exists(jsonl_path):
        # Try other possible locations
        for parent in [os.path.dirname(os.environ.get('RLM_SESSION_DIR', '')), '']:
            for root, _, files in os.walk('/home/USER/runs/paper/qwen-in-glm-hpl-u1/frozen'):
                if 'sessions' in root:
                    jsonl_path = os.path.join(root, session_name + '.jsonl')
                    if os.path.exists(jsonl_path):
                        break
        else:
            return {}

    G = {}
    seen = set()

    with open(jsonl_path, 'r') as f:
        content = f.read()

    # Find demo patterns
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n(.*?)(?=\n(Demo pair|\nTest input|\Z))', content, re.DOTALL):
        k = m[1]
        h, w = int(m[2]), int(m[3])
        grid_str = m[4].strip()

        if k in seen:
            continue
        seen.add(k)

        rows = grid_str.split('\n')[:h]
        if len(rows) != h:
            rows = rows[:h]

        valid = all(len(r) == w and all(x.isdigit() for x in r) for r in rows)
        if valid:
            G[k] = [[int(x) for x in r] for r in rows]

    return G

